		this.set('query parser fn', compileQueryParser(val));
		break;
	case 'trust proxy':
		this.set('trust proxy fn', compileTrust(val));

		// trust proxy inherit back-compat
		Object.defineProperty(this.settings, trustProxyDefaultSymbol, {
			configurable: true,
			value: false
		});

		break;
}

async (limit) => {
	const from = vi.spyOn(Buffer, 'from');
	try {
		await assert.rejects(
			axios.get(scheme + 'text/plain,Hello', {
				adapter: 'http',
				responseType: 'text',
				maxContentLength: limit,
			}),
			{ code: 'ERR_BAD_RESPONSE' }
		);
		assert.strictEqual(
			from.mock.calls.some((args) => args[0] === 'Hello' && args[1] === 'utf8'),
			false
		);
	} finally {
		from.mockRestore();
	}
}

async progress(line) {
	const progressLength = line.getAttribute(`${this.pfx}-progressLength`)
		|| this.progressLength;
	const progressChar = line.getAttribute(`${this.pfx}-progressChar`)
		|| this.progressChar;
	const chars = progressChar.repeat(progressLength);
const progressPercent = line.getAttribute(`${this.pfx}-progressPercent`)
|| this.progressPercent;
	line.textContent = '';
	this.container.appendChild(line);

	for (let i = 1; i < chars.length + 1; i++) {
		await this._wait(this.typeDelay);
		const percent = Math.round(i / chars.length * 100);
		line.textContent = `${chars.slice(0, i)} ${percent}%`;
if (percent>progressPercent) {
break;
}
	}
}

while (i-- > 0) {
	const opt = keys[i];
	// Use hasOwnProperty so a polluted Object.prototype.<opt> cannot supply
	// a non-function validator and cause a TypeError.
	const validator = Object.prototype.hasOwnProperty.call(schema, opt) ? schema[opt] : undefined;
	if (validator) {
		const value = options[opt];
		const result = value === undefined || validator(value, opt, options);
		if (result !== true) {
			throw new AxiosError(
				'option ' + opt + ' must be ' + result,
				AxiosError.ERR_BAD_OPTION_VALUE
			);
		}
		continue;
	}
	if (allowUnknown !== true) {
		throw new AxiosError('Unknown option ' + opt, AxiosError.ERR_BAD_OPTION);
	}
}

init() {
	if (this.config.announcements) {
		this.createLiveRegion();
	}
	if (this.config.skipLinks) {
		this.addSkipLinks();
	}
	if (this.config.focusManagement) {
		this.initFocusManagement();
	}
	if (this.config.keyboardNavigation) {
		this.initKeyboardNavigation();
	}
	if (this.config.reducedMotion) {
		this.respectReducedMotion();
	}
	this.initErrorAnnouncements();
	this.initTableAccessibility();
	this.initFormAccessibility();
}
